new="""void pipeUnpack(uint k0, uint tid, uint aP[A_ITERS], uvec4 aV[A_ITERS], uvec4 hdr[B_ITERS], uvec4 lo[B_ITERS], uvec4 hi[B_ITERS]) {
    [[unroll]] for (uint n = 0u; n < A_ITERS; ++n) {
